DO $$ BEGIN -- Check and add manufacture_order_id column IF NOT EXISTS ( SELECT 1 FROM information_schema.columns WHERE table_name='contract_material' AND column_name='manufacture_order_id' ) THEN ALTER TABLE contract_material ADD COLUMN manufacture_order_id UUID; END IF;
-- Check and add item_id column IF NOT EXISTS ( SELECT 1 FROM information_schema.columns WHERE table_name='material' AND column_name='item_id' ) THEN ALTER TABLE material ADD COLUMN item_id UUID; END IF;
END $$;

